def generate_row(s, C=16):
    """Generates a row based on a shift s. s=0 is identity, s=-1 is reverse."""
    if s == 0:
        return list(range(1, C + 1))
    elif s == -1:
        return list(range(C, 0, -1))
    else:
        # Positive shift s: R(i) = ((i + s - 1) mod C) + 1
        row = []
        for i in range(1, C + 1):
            val = (i + s - 1) % C + 1
            row.append(val)
        return row

def verify_separation(T, C=16):
    N = len(T)
    pairs = []
    for r in range(N):
        for s in range(r + 1, N):
            # Check if rows r and s are separated
            is_separated = False
            for c in range(C):
                diff = abs(T[r][c] - T[s][c])
                if diff >= 2:
                    is_separated = True
                    break
            if not is_separated:
                return False, (r, s)
            pairs.append((r, s))
    return True, pairs

# N=8 construction:
# R1: Shift 0 (Identity)
# R2: Shift -1 (Reverse)
# R3 to R8: Shifts 1 to 6
C = 16
N = 8
shifts = [0, -1, 1, 2, 3, 4, 5, 6]
T = [generate_row(s, C) for s in shifts]

# Verification
is_valid, pairs = verify_separation(T, C)

print(f"--- Table T ({N}x{C}) ---")
for i, row in enumerate(T):
    print(f"R{i+1}: {row}")

print("\n--- Verification Result ---")
if is_valid:
    print("SUCCESS: All pairwise separation conditions are satisfied.")
else:
    print("FAILURE: Found non-separated pair.")
    print(f"Pair indices (0-based): {pairs}")

